css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: calc(var(--loader-size) * .72); position: relative; border-radius: 8%; background: linear-gradient(#f1f5f9, #cbd5e1); box-shadow: inset 0 0 0 2px #94a3b8; }
.loader::before { content: ''; position: absolute; inset: 12% 32% 12% 8%; border-radius: 5px; background: radial-gradient(circle at 50% 34%, color-mix(in srgb, #000 42%, var(--accent-2)), #0b1220); }
.loader::after { content: ''; position: absolute; top: 14%; right: 7%; width: 17%; height: 72%; border-radius: 4px; background: repeating-linear-gradient(to bottom, #94a3b8 0 16%, #cbd5e1 16% 32%); }
.loader .plate { position: absolute; left: 14%; bottom: 20%; width: 42%; height: 11%; border-radius: 50%; background: color-mix(in srgb, #fff 30%, var(--accent-2)); animation: heat calc(var(--loader-speed) * 1.1) ease-in-out infinite; }
.loader .plate span { position: absolute; left: 50%; bottom: 30%; width: 26%; height: 190%; border-radius: 3px 3px 40% 40%; background: linear-gradient(color-mix(in srgb, #fff 24%, var(--accent)), var(--accent)); animation: turntable calc(var(--loader-speed) * 2.2) ease-in-out infinite; }
@keyframes turntable { 0%, 100% { transform: translateX(-160%) scale(.82); } 50% { transform: translateX(60%) scale(1.14); } }
@keyframes heat { 0%, 100% { box-shadow: 0 0 0 0 transparent; } 50% { box-shadow: 0 0 calc(var(--loader-size) * .09) color-mix(in srgb, #fff 30%, var(--accent)); } }
